KEYWORDS = {
    3: ["لا أرجع إلى الكفر أبدا", "التحرز", "نبادر الوسواس", "يتصدق بها كلها", "قيد الفتك", "فحلفت أن لا أقاتله", "في لفظه نكارة", "فاقض ديني", "يحفظ أموالهم", "لا، ولكن هو سلف", "حتى أنادي بالموسم أربع سنين"],
    4: ["سجود", "فهو وغيره منام", "حديث منكر", "إسناده واه", "إن عبد الرحمن لعظيم الرياء", "إني أخشى أن أكون قد هلكت", "عزله نفسه من الأمر", "فقسمه", "لا يعرف من بين عبيده", "دلني على السوق", "الغني الشاكر"],
    5: ["دعوة ذي النون", "ليت رجلا صالحا", "التقي، الغني، الخفي", "إني لا أدع ديني", "فلا تطعهما", "لا تعدل في الرعية", "فعفا عن عمر", "لولا اتقاء الله", "ولا خيانة", "لا أقاتل حتى", "الثلث كثير", "ورثتك أغنياء", "حتى اللقمة", "اعتزل سعد الفتنة", "كفنوني فيها"],
}

def generate():
    db = sqlite3.connect((ROOT / "data/library.sqlite3").as_uri() + "?mode=ro", uri=True)
    db.row_factory = sqlite3.Row
    source_bytes = (ROOT / "data/source.mARkdown").read_bytes()
    assert hashlib.sha256(source_bytes).hexdigest() == EXPECTED
    source = source_bytes.decode("utf-8")
    output = ROOT / "reference/pilot"
    output.mkdir(parents=True, exist_ok=True)
    for bid in (3,4,5):
        b = dict(db.execute("SELECT * FROM biographies WHERE id=?", (bid,)).fetchone())
        assert source[b["source_char_start"]:b["source_char_end"]] == b["full_text"]
        rows = [dict(r) for r in db.execute("SELECT * FROM segments WHERE biography_id=? ORDER BY segment_ordinal", (bid,))]
        by_n = {r["segment_ordinal"]:r for r in rows}
        def bounds(lo,hi):
            return by_n[lo]["source_char_start"], by_n[hi]["source_char_end"]
        data = {"source_sha256":EXPECTED,"biography_id":bid,"source_char_start":b["source_char_start"],"source_char_end":b["source_char_end"],"reviewer":"مراجعة نصية بواسطة وكيل","segments":[],"presentation":{},"gold":[]}
        ledger = {}
        for r in rows:
            notes = [note for lo,hi,note in GROUPS[bid] if lo<=r["segment_ordinal"]<=hi]
            assert len(notes)==1, r["segment_ordinal"]
            record = {"segment_id":r["id"],"assessment":"no_clear_topic","note":notes[0]+" فُحص المقطع ضمن سياقه؛ عدم وجود وسم مستقل لا يعني خلوه من المعاني.","topics":[],"existing_hits":[]}
            ledger[r["segment_ordinal"]]=record
            data["segments"].append(record)
        for anchor,lo,hi,topic,category,aliases,why,relation,scope,stance in TOPICS[bid]:
            ea,eb=bounds(anchor,anchor);ca,cb=bounds(lo,hi)
            ledger[anchor]["topics"].append({"topic":topic,"category":category,"aliases":aliases,"rationale":why,"relation_type":relation,"subject_scope":scope,"stance":stance,"evidence_start":ea,"evidence_end":eb,"context_start":ca,"context_end":cb})
            for n in range(lo,hi+1):ledger[n]["assessment"]="supported"
        hits = list(db.execute("SELECT h.*,s.segment_ordinal FROM topic_hits h JOIN segments s ON s.id=h.segment_id WHERE s.biography_id=? ORDER BY h.id",(bid,)))
        assert {r["id"] for r in hits}==set(HITS[bid])
        for hit in hits:
            decision,reason=HITS[bid][hit["id"]]
            ledger[hit["segment_ordinal"]]["existing_hits"].append({"hit_id":hit["id"],"decision":decision,"reason":reason})
        # These are known unsubstantiated supernatural reports with criticism
        # in their context, rather than accepted independent topical evidence.
        if bid==5:
            for n in (265,266,267,268,269,270,271,273,274,275):
                ledger[n]["assessment"]="uncertain"
                ledger[n]["note"]+=" حدود دلالة الخبر وصحته تحتاج مراجعة بشرية؛ لا يعتمد ككرامة محققة."
        p=data["presentation"]
        p["headings"]=[{"at":by_n[n]["source_char_start"],"label":label} for n,label in HEADINGS[bid]]
        for field,groups in (("quotes",QUOTES[bid]),("poetry",POETRY[bid])):
            p[field]=[{"start":bounds(lo,hi)[0],"end":bounds(lo,hi)[1]} for lo,hi in groups]
        # Only the explicit three-way enumeration is made into a list.
        p["lists"]=[]
        if bid==4:
            r=by_n[203];txt=r["text_original"];phrases=["ثلث يقرضهم ماله،","وثلث\n~~يقضي دينهم،","ويصل ثلثا."]
            items=[]
            for literal in phrases:
                at=txt.index(literal)+r["source_char_start"];items.append({"start":at,"end":at+len(literal)})
            p["lists"]=[{"start":items[0]["start"],"end":items[-1]["end"],"ordered":False,"items":items}]
            # Avoid conflicting structural overlays on the same passage.
            p["quotes"]=[r for r in p["quotes"] if r["start"]!=by_n[203]["source_char_start"]]
        p["footnotes"]=[{"start":b["source_char_start"]+m.start(),"end":b["source_char_start"]+m.end()} for m in re.finditer(r"\([0-9]+\)",b["full_text"])]
        assert len(p["footnotes"])=={3:80,4:73,5:98}[bid]
        def find_literals(literals):
            found=[]
            for literal in set(literals):
                # This allows the source's documented continuation lines while
                # matching only a reviewed list of literal person-name forms.
                pattern = r"(?<![\w])"+re.escape(literal).replace(r"\ ",r"(?:[ \t]|\r?\n~~)+")+r"(?![\w])"
                for m in re.finditer(pattern,b["full_text"]):
                    found.append({"start":b["source_char_start"]+m.start(),"end":b["source_char_start"]+m.end()})
            # Longest first removes redundant nested aliases for one visual mark.
            chosen=[]
            for span in sorted(found,key=lambda r:(-(r["end"]-r["start"]),r["start"])):
                if not any(span["start"]<s["end"] and span["end"]>s["start"] for s in chosen):chosen.append(span)
            return sorted(chosen,key=lambda r:r["start"])
        p["names"]=find_literals(NAME_ALLOWLIST)
        p["keywords"]=find_literals(KEYWORDS[bid])
        p["bold"]=[dict(r) for r in p["keywords"] if r["end"]-r["start"]>=12]
        for question,lo,hi in GOLD[bid]:
            a,z=bounds(lo,hi);data["gold"].append({"question":question,"start":a,"end":z})
        # Validate every datum against the bound source and biography, including
        # source ranges that carry no copied quotation in the JSON itself.
        for field in ("quotes","poetry","footnotes","names","keywords","bold"):
            for span in p[field]:assert b["source_char_start"]<=span["start"]<span["end"]<=b["source_char_end"]
        for record in data["segments"]:
            r=next(r for r in rows if r["id"]==record["segment_id"])
            for topic in record["topics"]:
                assert r["source_char_start"]<=topic["evidence_start"]<topic["evidence_end"]<=r["source_char_end"]
                assert b["source_char_start"]<=topic["context_start"]<=topic["evidence_start"]<topic["evidence_end"]<=topic["context_end"]<=b["source_char_end"]
        (output/f"biography-{bid}.json").write_text(json.dumps(data,ensure_ascii=False,indent=2)+"\n",encoding="utf-8")
        print(json.dumps({"biography":bid,"segments":len(rows),"topics":sum(len(r["topics"]) for r in data["segments"]),"existing_hits":len(hits),"footnotes":len(p["footnotes"]),"person_mentions_styled":len(p["names"]),"gold":len(data["gold"])},ensure_ascii=False))
    db.close()

if __name__=="__main__":generate()
